pts=[(3,0),(8,0),(9,0),(19,0),(4,1),(5,1),(11,1),(12,1),(20,1),(6,2),(10,2),(13,2),(17,2),(11,3),(22,3)]
def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
def hull(points):
 p=sorted(set(points)); lo=[]
 for x in p:
  while len(lo)>=2 and cross(lo[-2],lo[-1],x)<=0:lo.pop()
  lo.append(x)
 hi=[]
 for x in p[::-1]:
  while len(hi)>=2 and cross(hi[-2],hi[-1],x)<=0:hi.pop()
  hi.append(x)
 return lo[:-1]+hi[:-1]
h=hull(pts)
def inside(p,poly):
 signs=[]
 for i,a in enumerate(poly):
  b=poly[(i+1)%len(poly)]; z=cross(a,b,p)
  if z: signs.append(z>0)
 return not signs or all(s==signs[0] for s in signs)
